#!/usr/bin/env python3
# Generated By: Claude Code (Claude Opus 4.6)
"""Claude Code status line.

Output:
  Context | <reset>: <pct>% | ... | S/T/P: $x / $y / $z | model | session_id

Colors:
  Quota %:  green < 60%, yellow 60-89%, red >= 90%
  Costs:    cyan ramp (monotonic brightness), $15 steps, saturates at $195+
  Model:    orange
  Session:  purple

S/T/P = Session / Today / Project cost (USD).
Session ID appended for cross-session prompt log correlation.
"""

import json
import logging
import logging.handlers
import sys
import time
from pathlib import Path

# Ensure scripts/ parent is on sys.path so `from scripts.config` works
# when invoked directly (e.g. by Claude Code statusline command).
_scripts_parent = str(Path(__file__).resolve().parent.parent)
if _scripts_parent not in sys.path:
    sys.path.insert(0, _scripts_parent)

from scripts.config import (  # noqa: E402
    ANSI_GREEN,
    ANSI_ORANGE,
    ANSI_PURPLE,
    ANSI_RED,
    ANSI_RESET,
    ANSI_YELLOW,
    DATA_DIR,
    THRESHOLD_HIGH,
    THRESHOLD_MID,
)

LOG_DIR = DATA_DIR / "statusline-cache"
LOG_FILE = LOG_DIR / "statusline.log"

logger = logging.getLogger("statusline")
_log_configured = False


def _configure_logging():
    global _log_configured
    if _log_configured:
        return
    _log_configured = True
    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        handler = logging.handlers.RotatingFileHandler(
            str(LOG_FILE),
            maxBytes=256 * 1024,
            backupCount=1,
            encoding="utf-8",
        )
        handler.setFormatter(
            logging.Formatter("%(asctime)s %(levelname)s %(name)s: %(message)s")
        )
        logger.addHandler(handler)
        logger.setLevel(logging.DEBUG)
    except OSError:
        pass


def format_duration(seconds):
    """Format seconds as compact duration, max 2 units.

    Build full d+h+m+s, then truncate after the second unit.
    """
    seconds = max(0, int(seconds))
    days = seconds // 86400
    hours = (seconds % 86400) // 3600
    minutes = (seconds % 3600) // 60
    secs = seconds % 60

    parts = []
    if days:
        parts.append(f"{days}d")
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    if secs or not parts:
        parts.append(f"{secs}s")
    return "".join(parts[:2])


# Cyan monotonic ramp: follows 256-color cube diagonal for strict brightness increase.
# $15 steps, caps at $195+. Visible on both dark terminals and VSCode.
_COST_SHADES = [30, 37, 44, 51, 80, 87, 116, 123, 152, 159, 181, 188, 195, 231]
_COST_STEP = 15


def colorize_cost(amount):
    """Return dollar amount colored by absolute value.

    Single blue ramp, $15 steps, saturates at $195+.
    """
    idx = min(int(amount / _COST_STEP), len(_COST_SHADES) - 1)
    return f"\033[38;5;{_COST_SHADES[idx]}m${amount:.2f}{ANSI_RESET}"


def _pct_color(pct):
    """Return ANSI color code for a percentage value.

    Green  < THRESHOLD_MID
    Yellow THRESHOLD_MID to THRESHOLD_HIGH
    Red    >= THRESHOLD_HIGH
    """
    if pct >= THRESHOLD_HIGH * 100:
        return ANSI_RED
    elif pct >= THRESHOLD_MID * 100:
        return ANSI_YELLOW
    return ANSI_GREEN


def colorize_pct(pct):
    """Return pct formatted as a string with ANSI color based on magnitude."""
    return f"{_pct_color(pct)}{pct:.0f}%{ANSI_RESET}"


def format_remaining(resets_at):
    """Return compact time remaining until resets_at (Unix epoch seconds)."""
    if resets_at is None:
        return None
    try:
        remaining = int(float(resets_at) - time.time())
    except (TypeError, ValueError):
        return None
    if remaining <= 0:
        return "0s"
    return format_duration(remaining)


def main():
    _configure_logging()
    try:
        data = json.load(sys.stdin)
    except (json.JSONDecodeError, EOFError):
        print("Claude Code")
        return

    model = data.get("model", {}).get("display_name", "Claude")
    parts = []

    ctx = data.get("context_window", {})
    used_pct = ctx.get("used_percentage")
    if used_pct is not None:
        parts.append(f"Context: {colorize_pct(used_pct)}")

    from scripts.session_tracker import get_daily_cost, get_project_cost, track_session

    track_session(data)
    cost = (data.get("cost") or {}).get("total_cost_usd") or 0.0
    daily = get_daily_cost()
    project_dir = (data.get("workspace") or {}).get("project_dir")
    proj_cost = get_project_cost(project_dir) if project_dir else 0.0
    parts.append(
        f"S/T/P: {colorize_cost(cost)} / {colorize_cost(daily)}"
        f" / {colorize_cost(proj_cost)}"
    )

    parts.append(f"{ANSI_ORANGE}{model}{ANSI_RESET}")
    session_id = data.get("session_id", "")
    if session_id:
        parts.append(f"{ANSI_PURPLE}{session_id}{ANSI_RESET}")
    print(" | ".join(parts))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        _configure_logging()
        logger.exception("statusline crashed")
        print(f"{ANSI_RED}!ERR check {LOG_FILE}{ANSI_RESET}")
